// REST endpoint in Spring Boot - lightweight, JSON over HTTP
@RestController
@RequestMapping("/api/accounts")
public class AccountController {

    private final AccountService service;

    public AccountController(AccountService service) {
        this.service = service;
    }

    @GetMapping("/{id}/balance")
    public ResponseEntity<BalanceResponse> getBalance(@PathVariable String id) {
        var balance = service.balanceOf(id);   // -> {"accountId":"A1","balance":1499.50}
        return ResponseEntity.ok(new BalanceResponse(id, balance));
    }
}

record BalanceResponse(String accountId, BigDecimal balance) {}

// A SOAP equivalent would POST an XML <soap:Envelope> to a single endpoint
// described by a WSDL, called via a generated JAX-WS / Spring-WS client stub.
