// REST: fixed response shape, sometimes multiple round trips
@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserService service;

    public UserController(UserService service) {
        this.service = service;
    }

    @GetMapping("/{id}")
    public ResponseEntity<User> getUser(@PathVariable Long id) {
        return ResponseEntity.ok(service.findById(id)); // returns ALL user fields
    }
}

// GraphQL (spring-graphql) lets the client request only what it needs:
//   query { user(id: 1) { name, orders { id } } }
@Controller
class UserGraphQlController {

    private final UserService service;

    UserGraphQlController(UserService service) { this.service = service; }

    @QueryMapping
    public User user(@Argument Long id) {
        return service.findById(id);   // resolver returns just the requested slice
    }
}
